import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u02")
C = "B1-B2"
# Lições de aprofundamento (10–25): opinião, certeza, dados e temas sociais.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Parece que…", "Het lijkt erop dat het gaat regenen.",
  ["Exprimir probabilidade e incerteza com cuidado"],
  vocab=[X("v-het-lijkt-erop","het lijkt erop dat…","parece que…"), X("v-naar-alle-waarschijnlijkheid","naar alle waarschijnlijkheid","com toda a probabilidade"),
         X("v-het-is-de-vraag-of","het is de vraag of…","não se sabe se…|resta saber se…")],
  ex=[("Het lijkt erop dat de trein vertraging heeft.","Parece que o comboio está atrasado."),("Naar alle waarschijnlijkheid gaat het feest door.","Com toda a probabilidade a festa vai realizar-se."),("Het is de vraag of dat plan werkt.","Resta saber se esse plano funciona.")],
  review=["v-waarschijnlijk","v-twijfel"],
  cefr=C, exs=[
    MA([("het lijkt erop dat…","parece que…"),("naar alle waarschijnlijkheid","com toda a probabilidade"),("het is de vraag of…","resta saber se…"),("twijfel","dúvida")], "Probabilidade.", ["v-het-lijkt-erop","v-naar-alle-waarschijnlijkheid","v-het-is-de-vraag-of","v-twijfel"]),
    MC("Qual exprime MAIS dúvida?", ["*Het is de vraag of het lukt.","Naar alle waarschijnlijkheid lukt het.|Muito provável.","Het lijkt erop dat het lukt.|Provável."], "Graus.", ["v-het-is-de-vraag-of"]),
    TR("pt-nl","Parece que o comboio está atrasado.", ["Het lijkt erop dat de trein vertraging heeft","Het lijkt erop dat de trein vertraagd is"], "het lijkt erop dat.", ["v-het-lijkt-erop"]),
    TR("pt-nl","Resta saber se isso funciona.", ["Het is de vraag of dat werkt","Het is de vraag of het werkt"], "of + verbo no fim.", ["v-het-is-de-vraag-of"]),
    FB("Het is de vraag ___ de minister blijft.", ["of"], "of = se.", ["v-het-is-de-vraag-of"], choices=["of","dat","als"], tr="Resta saber se o ministro fica."),
    FE(["Het","lijkt","erop","dat","hij","komt","niet."], 5, "niet", "Subordinada: …dat hij niet komt.", ["v-het-lijkt-erop"]),
    LI("Naar alle waarschijnlijkheid wordt het morgen droog.", ["Naar alle waarschijnlijkheid wordt het morgen droog"], "Com toda a probabilidade amanhã não chove.", "Previsão.", ["v-naar-alle-waarschijnlijkheid"]),
    DL([("Collega","Krijgen we dit jaar een bonus?","Vamos ter bónus este ano?"),("Jij","","")], ["*Het lijkt erop van wel, maar het is de vraag hoe hoog die is.","Zeker weten!|Certeza sem base.","Het is de vraag.|Incompleto."], "Prudência.", ["v-het-lijkt-erop"]),
    WO("Parece que vai chover.", ["Het","lijkt","erop","dat","het","gaat","regenen"], "Ordem.", ["v-het-lijkt-erop"]),
  ], diff=4, mins=5)

L(11, "Certeza absoluta", "Het staat vast dat…",
  ["Exprimir certeza com expressões formais"],
  vocab=[X("v-het-staat-vast","het staat vast dat…","é certo que…|está assente que…"), X("v-zonder-enige-twijfel","zonder enige twijfel","sem qualquer dúvida")],
  ex=[("Het staat vast dat de bouw volgend jaar begint.","É certo que a construção começa no próximo ano."),("Dit is zonder enige twijfel het beste restaurant van de stad.","Este é sem qualquer dúvida o melhor restaurante da cidade.")],
  review=["v-ongetwijfeld","v-ik-ben-ervan-overtuigd"],
  cefr=C, exs=[
    MA([("het staat vast dat…","é certo que…"),("zonder enige twijfel","sem qualquer dúvida"),("ongetwijfeld","sem dúvida"),("ik ben ervan overtuigd","estou convencido")], "Certeza.", ["v-het-staat-vast","v-zonder-enige-twijfel","v-ongetwijfeld","v-ik-ben-ervan-overtuigd"]),
    TR("pt-nl","É certo que a construção começa no próximo ano.", ["Het staat vast dat de bouw volgend jaar begint"], "het staat vast.", ["v-het-staat-vast"]),
    TR("pt-nl","Sem qualquer dúvida.", ["Zonder enige twijfel","Zonder twijfel"], "Expressão.", ["v-zonder-enige-twijfel"]),
    MC("«Het staat vast» usa-se para…", ["*algo decidido ou comprovado","uma suspeita|Não.","uma pergunta|Não."], "Certeza.", ["v-het-staat-vast"]),
    FB("Zonder ___ twijfel is dit de beste keuze.", ["enige"], "Expressão fixa.", ["v-zonder-enige-twijfel"], choices=["enige","enig","geen"], tr="Sem qualquer dúvida, esta é a melhor escolha."),
    FE(["Het","staat","vast","dat","de","datum","verandert","niet."], 6, "niet", "Subordinada: …dat de datum niet verandert.", ["v-het-staat-vast"]),
    MC("Num texto argumentativo, usar «het staat vast» sem provas é…", ["*arriscado: parece certeza sem fundamento","sempre recomendado|Não.","informal|Não."], "Cuidado.", ["v-het-staat-vast"]),
    LI("Eén ding staat vast: we moeten nu beslissen.", ["Eén ding staat vast: we moeten nu beslissen","Een ding staat vast: we moeten nu beslissen","Eén ding staat vast, we moeten nu beslissen"], "Uma coisa é certa: temos de decidir agora.", "Variante.", ["v-het-staat-vast"]),
    WO("Uma coisa é certa.", ["Eén","ding","staat","vast"], "Ordem.", ["v-het-staat-vast"]),
  ], diff=4, mins=5)

L(12, "Metade, um terço, um quarto", "Een derde van de inwoners fietst.",
  ["Falar de proporções num texto ou gráfico"],
  vocab=[X("v-de-helft","de helft","a metade"), X("v-een-derde","een derde","um terço"),
         X("v-een-kwart","een kwart","um quarto"), N("v-minderheid","minderheid","minoria","de","minderheden")],
  ex=[("De helft van de klas is ziek.","Metade da turma está doente."),("Een derde van de deelnemers was tevreden.","Um terço dos participantes estava satisfeito."),("Een kwart van het budget gaat naar onderwijs.","Um quarto do orçamento vai para a educação."),("Een kleine minderheid was tegen.","Uma pequena minoria era contra.")],
  review=["v-meerderheid","v-procent","v-een-op-de"],
  cefr=C, exs=[
    MA([("de helft","a metade"),("een derde","um terço"),("een kwart","um quarto"),("minderheid","minoria")], "Proporções.", ["v-de-helft","v-een-derde","v-een-kwart","v-minderheid"]),
    MC("«Een op de vier» é o mesmo que…", ["*een kwart","een derde|1/3.","de helft|1/2."], "1/4.", ["v-een-kwart","v-een-op-de"]),
    MC("«Het grootste deel» é…", ["*a maioria","a minoria|Não.","um terço|Não."], "Sinónimo de meerderheid.", ["v-meerderheid"]),
    TR("pt-nl","Metade da turma está doente.", ["De helft van de klas is ziek"], "De helft van.", ["v-de-helft"]),
    TR("pt-nl","Uma pequena minoria era contra.", ["Een kleine minderheid was tegen","Een kleine minderheid was ertegen"], "minderheid.", ["v-minderheid"]),
    CO("text","Enquête in de wijk (fictief)","Aan een enquête in de wijk deden 200 bewoners mee. De helft vindt dat er te weinig groen is. Een derde wil meer speelplekken voor kinderen. Een kwart klaagt over geluidsoverlast. Slechts een kleine minderheid is helemaal tevreden.",
       [("Quantos participaram?", ["*200","100","50"]),("Quantos querem mais espaços verdes?", ["*Metade","Um terço","Um quarto"]),("Quem está totalmente satisfeito?", ["*Uma pequena minoria","A maioria","Ninguém"])],
       "Inquérito fictício para praticar proporções.", ["v-de-helft","v-een-derde","v-een-kwart","v-minderheid"]),
    FB("___ van de bewoners klaagt over lawaai: 25%.", ["Een kwart"], "25%.", ["v-een-kwart"], choices=["Een kwart","Een derde","De helft"], tr="Um quarto dos moradores queixa-se do barulho."),
    FE(["Een","derde","van","de","deelnemers","waren","tevreden."], 5, "was", "Concordância habitual com «een derde»: singular.", ["v-een-derde"]),
    LI("Meer dan de helft stemde voor het plan.", ["Meer dan de helft stemde voor het plan"], "Mais de metade votou a favor do plano.", "Uso.", ["v-de-helft"]),
  ], diff=4, mins=6)

L(13, "Tendências: subir, cair, duplicar", "Het aantal fietsers is verdubbeld.",
  ["Descrever tendências e mudanças em números"],
  vocab=[X("v-verdubbelen","verdubbelen","duplicar","verb"), X("v-halveren","halveren","reduzir para metade","verb"),
         N("v-stijging","stijging","subida|aumento","de","stijgingen"), N("v-daling","daling","descida|queda","de","dalingen")],
  ex=[("Het aantal fietsers is in tien jaar verdubbeld.","O número de ciclistas duplicou em dez anos."),("De wachttijd is gehalveerd.","O tempo de espera foi reduzido para metade."),("Er is een sterke stijging van de prijzen.","Há uma forte subida dos preços."),("We zien een lichte daling.","Vemos uma ligeira descida.")],
  review=["v-stijgen","v-dalen"],
  cefr=C, exs=[
    MA([("verdubbelen","duplicar"),("halveren","reduzir para metade"),("stijging","subida"),("daling","descida")], "Tendências.", ["v-verdubbelen","v-halveren","v-stijging","v-daling"]),
    MC("De 10 para 5 é…", ["*halveren","verdubbelen|É o contrário.","gelijk blijven|Não."], "Metade.", ["v-halveren"]),
    MC("Verbo «stijgen» → substantivo:", ["*de stijging","het stijgen (só como infinitivo)|Possível, mas o nome é stijging.","de stijger|Não."], "-ing.", ["v-stijging"]),
    TR("pt-nl","O número de ciclistas duplicou.", ["Het aantal fietsers is verdubbeld","Het aantal fietsers verdubbelde"], "zijn + verdubbeld.", ["v-verdubbelen"]),
    TR("pt-nl","Vemos uma ligeira descida.", ["We zien een lichte daling","Wij zien een lichte daling"], "daling.", ["v-daling"]),
    FB("Er is een sterke ___ van de huurprijzen.", ["stijging"], "Subida.", ["v-stijging"], choices=["stijging","daling","stijgen"], tr="Há uma forte subida das rendas."),
    CJ("halveren","de wachttijd","De wachttijd is ___.", ["gehalveerd"], "ge- + halveer + d.", ["v-halveren"], tense="passado-perfeito"),
    FE(["Het","aantal","is","verdubbelt."], 3, "verdubbeld.", "Particípio: -d (l não está em kofschip).", ["v-verdubbelen"]),
    LI("Na een daling in het voorjaar stegen de prijzen weer.", ["Na een daling in het voorjaar stegen de prijzen weer"], "Depois de uma descida na primavera, os preços voltaram a subir.", "Narrar tendências.", ["v-daling","v-stijgen"]),
  ], diff=4, mins=6)

