    LI("Ter illustratie laat ik u een foto zien.", ["Ter illustratie laat ik u een foto zien","Ter illustratie laat ik jullie een foto zien"], "A título de ilustração, mostro-vos uma fotografia.", "Apresentação.", ["v-ter-illustratie"]),
    WO("Pensa no clima.", ["Denk","aan","het","klimaat"], "Ordem.", ["v-denk-aan"]),
